[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>GreenBean Coffee — Your Daily Coffee Ritual</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Inter:wght@300;400;500;600&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green: #00824A;
      --green-dark: #006B3C;
      --green-light: #E6F4ED;
      --forest: #32462F;
      --cream: #F3CEA1;
      --cream-light: #FDF6EC;
      --cream-mid: #F9EDD8;
      --brown: #5C3D1E;
      --text-dark: #1A1A1A;
      --text-mid: #4A4A4A;
      --text-light: #767676;
      --white: #FFFFFF;
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --radius-xl: 32px;
      --shadow-sm: 0 2px 8px rgba(0,0,0,0.08);
      --shadow-md: 0 4px 20px rgba(0,0,0,0.10);
      --shadow-lg: 0 8px 40px rgba(0,0,0,0.14);
      --transition: 200ms ease;
    }

    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; color: var(--text-dark); background: var(--white); overflow-x: hidden; }

    h1, h2, h3, h4, h5 { font-family: 'DM Sans', sans-serif; line-height: 1.2; }
    p { line-height: 1.65; }
    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }

    /* ── HEADER ── */
    .site-header {
      position: sticky; top: 0; z-index: 100;
      background: var(--white);
      border-bottom: 1px solid rgba(0,0,0,0.06);
      box-shadow: var(--shadow-sm);
    }
    .header-inner {
      max-width: 1280px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 24px; height: 64px; gap: 16px;
    }
    .logo {
      display: flex; align-items: center; gap: 10px;
      font-family: 'DM Sans', sans-serif; font-weight: 700;
      font-size: 20px; color: var(--green); white-space: nowrap;
      flex-shrink: 0;
    }
    .logo svg { width: 36px; height: 36px; }
    .primary-nav { display: flex; align-items: center; gap: 4px; }
    .primary-nav a {
      padding: 8px 14px; border-radius: 100px;
      font-size: 15px; font-weight: 500; color: var(--text-dark);
      transition: background var(--transition), color var(--transition);
      white-space: nowrap;
    }
    .primary-nav a:hover { background: var(--green-light); color: var(--green); }
    .primary-nav a.active { background: var(--green-light); color: var(--green); }
    .header-actions { display: flex; align-items: center; gap: 8px; }
    .btn-ghost {
      padding: 8px 16px; border-radius: 100px;
      font-size: 14px; font-weight: 500; color: var(--text-dark);
      transition: background var(--transition);
    }
    .btn-ghost:hover { background: var(--cream-light); }
    .btn-primary {
      padding: 9px 20px; border-radius: 100px;
      background: var(--green); color: var(--white);
      font-size: 14px; font-weight: 600;
      transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
    }
    .btn-primary:hover { background: var(--green-dark); box-shadow: 0 4px 14px rgba(0,130,74,0.3); }
    .mobile-menu-btn { display: none; padding: 8px; border-radius: 8px; }
    .mobile-menu-btn:hover { background: var(--cream-light); }
    .mobile-nav {
      display: none; position: fixed; top: 64px; left: 0; right: 0; bottom: 0;
      background: var(--white); z-index: 99; padding: 16px 24px 32px;
      flex-direction: column; gap: 4px; overflow-y: auto;
    }
    .mobile-nav.open { display: flex; }
    .mobile-nav a {
      padding: 14px 16px; border-radius: var(--radius-sm);
      font-size: 17px; font-weight: 500; color: var(--text-dark);
      transition: background var(--transition);
    }
    .mobile-nav a:hover, .mobile-nav a.active { background: var(--green-light); color: var(--green); }
    .mobile-nav-divider { height: 1px; background: rgba(0,0,0,0.06); margin: 8px 0; }
    .mobile-nav .btn-primary { text-align: center; margin-top: 8px; }

    /* ── COOKIE BANNER ── */
    .cookie-banner {
      position: fixed; bottom: 24px; left: 24px; right: 24px;
      max-width: 680px; margin: 0 auto;
      background: var(--forest); color: var(--white);
      border-radius: var(--radius-md); padding: 20px 24px;
      box-shadow: var(--shadow-lg);
      z-index: 200;
      display: flex; gap: 16px; align-items: flex-start;
      transition: opacity 0.3s, transform 0.3s;
    }
    .cookie-banner.hidden { opacity: 0; pointer-events: none; transform: translateY(16px); }
    .cookie-content { flex: 1; }
    .cookie-content h3 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
    .cookie-content p { font-size: 13px; opacity: 0.85; line-height: 1.5; }
    .cookie-actions { display: flex; gap: 8px; flex-shrink: 0; align-items: center; flex-wrap: wrap; }
    .cookie-btn-ghost {
      padding: 8px 16px; border-radius: 100px; font-size: 13px; font-weight: 500;
      border: 1.5px solid rgba(255,255,255,0.4); color: var(--white);
      transition: background var(--transition);
    }
    .cookie-btn-ghost:hover { background: rgba(255,255,255,0.12); }
    .cookie-btn-agree {
      padding: 8px 20px; border-radius: 100px; font-size: 13px; font-weight: 600;
      background: var(--cream); color: var(--forest);
      transition: background var(--transition);
    }
    .cookie-btn-agree:hover { background: #e8c089; }

    /* ── HERO ── */
    .hero {
      position: relative; min-height: 80vh;
      background: linear-gradient(135deg, var(--forest) 0%, #1a2e18 50%, #0f1a0d 100%);
      display: flex; align-items: center; overflow: hidden;
    }
    .hero-bg-shapes {
      position: absolute; inset: 0; overflow: hidden; pointer-events: none;
    }
    .hero-bg-shapes::before {
      content: '';
      position: absolute; top: -20%; right: -10%;
      width: 70%; height: 140%;
      background: radial-gradient(ellipse, rgba(0,130,74,0.35) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero-bg-shapes::after {
      content: '';
      position: absolute; bottom: -30%; left: -5%;
      width: 50%; height: 80%;
      background: radial-gradient(ellipse, rgba(243,206,161,0.15) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero-inner {
      max-width: 1280px; margin: 0 auto; padding: 80px 24px;
      position: relative; z-index: 1;
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .hero-content { color: var(--white); }
    .hero-eyebrow {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(243,206,161,0.15); border: 1px solid rgba(243,206,161,0.3);
      padding: 6px 14px; border-radius: 100px; margin-bottom: 24px;
      font-size: 13px; font-weight: 500; color: var(--cream);
    }
    .hero-eyebrow-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--cream); }
    .hero-title {
      font-size: clamp(40px, 5vw, 64px); font-weight: 700; line-height: 1.1;
      margin-bottom: 24px; letter-spacing: -0.02em;
    }
    .hero-title em { font-style: normal; color: var(--cream); }
    .hero-subtitle {
      font-size: 18px; opacity: 0.8; margin-bottom: 36px; line-height: 1.6; max-width: 420px;
    }
    .hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
    .btn-hero-primary {
      padding: 14px 32px; border-radius: 100px; font-size: 16px; font-weight: 700;
      background: var(--green); color: var(--white);
      transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
      box-shadow: 0 4px 24px rgba(0,130,74,0.4);
    }
    .btn-hero-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: 0 6px 30px rgba(0,130,74,0.5); }
    .btn-hero-ghost {
      padding: 14px 32px; border-radius: 100px; font-size: 16px; font-weight: 600;
      border: 2px solid rgba(255,255,255,0.35); color: var(--white);
      transition: background var(--transition), border-color var(--transition);
    }
    .btn-hero-ghost:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.6); }
    .hero-visual {
      display: flex; justify-content: center; align-items: center;
    }
    .hero-card {
      background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12);
      backdrop-filter: blur(12px); border-radius: var(--radius-xl);
      padding: 28px; width: 100%; max-width: 340px;
    }
    .hero-coffee-img {
      width: 100%; aspect-ratio: 4/3; border-radius: var(--radius-lg);
      background: linear-gradient(135deg, #3a5a32, #2d4527);
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 20px; overflow: hidden; position: relative;
    }
    .coffee-art {
      width: 120px; height: 120px;
      background: radial-gradient(circle at 40% 35%, #c8860a 0%, #8B5E2B 40%, #3d2a12 100%);
      border-radius: 50%; position: relative; box-shadow: 0 8px 32px rgba(0,0,0,0.4);
    }
    .coffee-art::after {
      content: '';
      position: absolute; inset: 12px;
      background: radial-gradient(circle at 35% 30%, rgba(255,255,255,0.15), transparent 60%);
      border-radius: 50%;
    }
    .coffee-steam { position: absolute; top: 10px; left: 50%; transform: translateX(-50%); display: flex; gap: 8px; }
    .steam-line {
      width: 3px; border-radius: 2px;
      background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.5), transparent);
      animation: steam 2s ease-in-out infinite;
    }
    .steam-line:nth-child(1) { height: 30px; animation-delay: 0s; }
    .steam-line:nth-child(2) { height: 22px; animation-delay: 0.4s; }
    .steam-line:nth-child(3) { height: 26px; animation-delay: 0.8s; }
    @keyframes steam { 0%,100%{transform:translateY(0) scaleX(1);opacity:0.7} 50%{transform:translateY(-8px) scaleX(1.2);opacity:1} }
    .hero-card-text { color: var(--white); }
    .hero-card-label { font-size: 12px; font-weight: 500; opacity: 0.6; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; }
    .hero-card-name { font-family: 'DM Sans', sans-serif; font-size: 22px; font-weight: 700; margin-bottom: 4px; }
    .hero-card-desc { font-size: 14px; opacity: 0.7; }
    .hero-stats {
      display: flex; gap: 20px; margin-top: 16px; padding-top: 16px;
      border-top: 1px solid rgba(255,255,255,0.1);
    }
    .hero-stat { flex: 1; text-align: center; }
    .hero-stat-value { font-family: 'DM Sans', sans-serif; font-size: 20px; font-weight: 700; color: var(--cream); }
    .hero-stat-label { font-size: 11px; opacity: 0.6; margin-top: 2px; }

    /* ── PROMO SECTION ── */
    .promo-section {
      padding: 80px 24px;
      max-width: 1280px; margin: 0 auto;
    }
    .promo-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
    .promo-card {
      border-radius: var(--radius-xl); overflow: hidden; position: relative;
      min-height: 400px; display: flex; flex-direction: column; justify-content: flex-end;
      padding: 36px; cursor: pointer;
      transition: transform 0.25s ease, box-shadow 0.25s ease;
    }
    .promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
    .promo-card-bg {
      position: absolute; inset: 0; z-index: 0;
    }
    .promo-card-overlay {
      position: absolute; inset: 0; z-index: 1;
      background: linear-gradient(to top, rgba(0,0,0,0.75) 0%, transparent 60%);
    }
    .promo-card-content { position: relative; z-index: 2; color: var(--white); }
    .promo-tag {
      display: inline-block; padding: 4px 12px; border-radius: 100px;
      font-size: 12px; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase;
      margin-bottom: 12px;
    }
    .promo-card h2 { font-size: clamp(22px, 2.5vw, 32px); font-weight: 700; margin-bottom: 10px; }
    .promo-card p { font-size: 15px; opacity: 0.85; line-height: 1.55; margin-bottom: 20px; max-width: 380px; }
    .btn-white {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 11px 24px; border-radius: 100px;
      background: var(--white); color: var(--text-dark);
      font-size: 14px; font-weight: 600;
      transition: background var(--transition), transform var(--transition);
    }
    .btn-white:hover { background: var(--cream); }
    .btn-white svg { width: 16px; height: 16px; }

    /* Featured product card */
    .card-featured .promo-card-bg { background: linear-gradient(135deg, #00824A, #004d2e); }
    .card-featured .promo-tag { background: rgba(243,206,161,0.2); color: var(--cream); }

    /* Afternoon card */
    .card-afternoon .promo-card-bg { background: linear-gradient(135deg, #8B6914, #5C3D1E); }
    .card-afternoon .promo-tag { background: rgba(255,200,100,0.2); color: #FFD580; }

    /* ── AI RECOMMENDATION ── */
    .ai-section {
      background: var(--forest);
      padding: 60px 24px;
    }
    .ai-inner {
      max-width: 1280px; margin: 0 auto;
      display: grid; grid-template-columns: 1fr auto; gap: 40px; align-items: center;
    }
    .ai-content { color: var(--white); }
    .ai-badge {
      display: inline-flex; align-items: center; gap: 8px; margin-bottom: 16px;
      padding: 6px 14px; border-radius: 100px;
      background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.15);
      font-size: 13px; font-weight: 500; color: rgba(255,255,255,0.8);
    }
    .ai-content h2 { font-size: clamp(24px, 3vw, 40px); font-weight: 700; margin-bottom: 12px; }
    .ai-content p { font-size: 16px; opacity: 0.75; line-height: 1.6; max-width: 520px; }
    .btn-ai {
      display: inline-flex; align-items: center; gap: 10px;
      margin-top: 24px;
      padding: 12px 28px; border-radius: 100px;
      background: var(--cream); color: var(--forest);
      font-size: 15px; font-weight: 600;
      transition: background var(--transition), transform var(--transition);
    }
    .btn-ai:hover { background: #e8c089; transform: translateY(-1px); }
    .ai-visual {
      width: 200px; height: 200px; flex-shrink: 0;
      background: radial-gradient(circle at 40% 40%, rgba(0,130,74,0.5), rgba(50,70,47,0.3) 60%);
      border-radius: 50%; border: 2px solid rgba(0,130,74,0.3);
      display: flex; align-items: center; justify-content: center;
      position: relative;
    }
    .ai-visual-inner {
      width: 120px; height: 120px;
      background: radial-gradient(circle, rgba(0,130,74,0.6), rgba(0,50,30,0.8));
      border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
    }

    /* ── SEASONAL HIGHLIGHTS ── */
    .seasonal-section { padding: 80px 24px; background: var(--cream-light); }
    .seasonal-inner { max-width: 1280px; margin: 0 auto; }
    .section-header { text-align: center; margin-bottom: 48px; }
    .section-eyebrow {
      font-size: 13px; font-weight: 600; color: var(--green);
      text-transform: uppercase; letter-spacing: 0.1em; margin-bottom: 12px;
    }
    .section-title { font-size: clamp(28px, 4vw, 48px); font-weight: 700; color: var(--text-dark); }
    .section-sub { font-size: 17px; color: var(--text-mid); margin-top: 12px; max-width: 520px; margin-left: auto; margin-right: auto; }
    .seasonal-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
    .seasonal-card {
      border-radius: var(--radius-xl); overflow: hidden;
      background: var(--white); box-shadow: var(--shadow-sm);
      display: flex; flex-direction: column;
      transition: transform 0.25s, box-shadow 0.25s;
    }
    .seasonal-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .seasonal-img {
      aspect-ratio: 16/9; position: relative; overflow: hidden;
    }
    .seasonal-img-bg {
      position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
    }
    .seasonal-img-placeholder {
      width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; position: relative;
    }
    .seasonal-content { padding: 28px 28px 32px; flex: 1; display: flex; flex-direction: column; }
    .seasonal-tag {
      display: inline-flex; align-items: center; gap: 6px;
      font-size: 12px; font-weight: 600; color: var(--green);
      text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 12px;
    }
    .seasonal-tag-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); }
    .seasonal-content h3 { font-size: 24px; font-weight: 700; margin-bottom: 10px; }
    .seasonal-content p { font-size: 15px; color: var(--text-mid); line-height: 1.65; flex: 1; }
    .btn-green {
      display: inline-flex; align-items: center; gap: 8px; margin-top: 20px;
      padding: 12px 24px; border-radius: 100px; align-self: flex-start;
      background: var(--green); color: var(--white); font-size: 14px; font-weight: 600;
      transition: background var(--transition), transform var(--transition);
    }
    .btn-green:hover { background: var(--green-dark); transform: translateY(-1px); }
    .btn-outline-green {
      display: inline-flex; align-items: center; gap: 8px; margin-top: 20px;
      padding: 11px 24px; border-radius: 100px; align-self: flex-start;
      border: 2px solid var(--green); color: var(--green); font-size: 14px; font-weight: 600;
      transition: background var(--transition), color var(--transition);
    }
    .btn-outline-green:hover { background: var(--green); color: var(--white); }

    /* Seasonal bg colors */
    .seasonal-fruity .seasonal-img-placeholder { background: linear-gradient(135deg, #F3A857, #E87B3C); }
    .seasonal-spring .seasonal-img-placeholder { background: linear-gradient(135deg, #9B7FC5, #6B4BA0); }
    .seasonal-items { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 12px; margin-bottom: 4px; }
    .seasonal-item-chip {
      padding: 4px 12px; border-radius: 100px; font-size: 12px; font-weight: 500;
      background: var(--cream-mid); color: var(--brown);
    }

    /* ── NONDAIRY PROMO ── */
    .nondairy-section { padding: 80px 24px; }
    .nondairy-inner {
      max-width: 1280px; margin: 0 auto;
      background: var(--green); border-radius: var(--radius-xl);
      padding: 60px 48px;
      display: grid; grid-template-columns: 1fr auto; gap: 40px; align-items: center;
    }
    .nondairy-content { color: var(--white); }
    .nondairy-content h2 { font-size: clamp(28px, 3vw, 44px); font-weight: 700; margin-bottom: 16px; }
    .nondairy-content p { font-size: 17px; opacity: 0.85; line-height: 1.6; max-width: 440px; margin-bottom: 28px; }
    .nondairy-milks { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 28px; }
    .milk-chip {
      padding: 6px 16px; border-radius: 100px;
      background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.25);
      font-size: 14px; font-weight: 500; color: var(--white);
    }
    .btn-cream {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 13px 28px; border-radius: 100px;
      background: var(--cream); color: var(--forest);
      font-size: 15px; font-weight: 700;
      transition: background var(--transition), transform var(--transition);
    }
    .btn-cream:hover { background: #e8c089; transform: translateY(-1px); }
    .nondairy-visual { display: flex; gap: 12px; flex-shrink: 0; }
    .milk-bottle {
      width: 60px; border-radius: 30px;
      display: flex; flex-direction: column; align-items: center; justify-content: flex-end;
      padding: 10px 0; gap: 6px;
      background: rgba(255,255,255,0.12); border: 1px solid rgba(255,255,255,0.2);
      transition: transform 0.3s;
    }
    .milk-bottle:hover { transform: translateY(-6px); }
    .milk-bottle-tall { height: 140px; }
    .milk-bottle-mid { height: 110px; }
    .milk-bottle-short { height: 90px; }
    .milk-dot { width: 12px; height: 12px; border-radius: 50%; background: rgba(255,255,255,0.5); }

    /* ── FOOTER ── */
    .site-footer { background: var(--forest); color: var(--white); }
    .footer-main {
      max-width: 1280px; margin: 0 auto;
      padding: 60px 24px 40px;
      display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
    }
    .footer-col-title {
      font-family: 'DM Sans', sans-serif; font-size: 13px; font-weight: 700;
      text-transform: uppercase; letter-spacing: 0.1em;
      color: var(--cream); margin-bottom: 16px;
    }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-col ul li a {
      font-size: 14px; color: rgba(255,255,255,0.7);
      transition: color var(--transition);
    }
    .footer-col ul li a:hover { color: var(--white); }
    .footer-bottom {
      max-width: 1280px; margin: 0 auto;
      padding: 20px 24px; border-top: 1px solid rgba(255,255,255,0.1);
      display: flex; gap: 16px; align-items: center; justify-content: space-between;
      flex-wrap: wrap;
    }
    .footer-logo { font-family: 'DM Sans', sans-serif; font-size: 18px; font-weight: 700; color: var(--cream); }
    .footer-legal { font-size: 12px; color: rgba(255,255,255,0.5); }
    .footer-social { display: flex; gap: 12px; }
    .social-link {
      width: 36px; height: 36px; border-radius: 50%;
      background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center;
      transition: background var(--transition);
    }
    .social-link:hover { background: rgba(255,255,255,0.2); }
    .social-link svg { width: 16px; height: 16px; fill: var(--white); }

    /* Footer accordion (mobile) */
    .footer-accordion-btn {
      display: none; width: 100%; text-align: left;
      padding: 14px 0; border-bottom: 1px solid rgba(255,255,255,0.1);
      background: none; color: var(--cream);
      font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em;
      align-items: center; justify-content: space-between;
    }
    .footer-accordion-btn svg { width: 18px; height: 18px; transition: transform 0.2s; }
    .footer-accordion-btn.open svg { transform: rotate(180deg); }
    .footer-col-content { display: block; }

    /* ── DECORATIVE COFFEE ELEMENTS ── */
    .coffee-bean {
      width: 80px; height: 100px;
      background: radial-gradient(ellipse at 40% 30%, #c8860a 0%, #7B4A1E 50%, #3d2a12 100%);
      border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
      position: relative;
    }
    .coffee-bean::after {
      content: '';
      position: absolute; inset: 20% 47%;
      background: rgba(0,0,0,0.3);
      border-radius: 40%;
    }

    /* ── RESPONSIVE ── */
    @media (max-width: 1024px) {
      .footer-main { grid-template-columns: repeat(3, 1fr); }
    }
    @media (max-width: 768px) {
      .primary-nav, .header-actions { display: none; }
      .mobile-menu-btn { display: flex; }
      .hero-inner { grid-template-columns: 1fr; text-align: center; }
      .hero-content { order: 2; }
      .hero-visual { order: 1; }
      .hero-actions { justify-content: center; }
      .hero-subtitle { margin: 0 auto 36px; }
      .promo-grid { grid-template-columns: 1fr; }
      .promo-card { min-height: 320px; }
      .ai-inner { grid-template-columns: 1fr; }
      .ai-visual { display: none; }
      .seasonal-grid { grid-template-columns: 1fr; }
      .nondairy-inner { grid-template-columns: 1fr; padding: 36px 24px; }
      .nondairy-visual { justify-content: center; }
      .footer-main { grid-template-columns: 1fr; gap: 0; padding: 32px 24px; }
      .footer-col-title { display: none; }
      .footer-accordion-btn { display: flex; }
      .footer-col-content { display: none; padding: 12px 0 16px; }
      .footer-col-content.open { display: block; }
      .footer-bottom { flex-direction: column; text-align: center; }
    }
    @media (max-width: 480px) {
      .hero { min-height: 70vh; }
      .promo-section, .seasonal-section, .nondairy-section { padding: 48px 16px; }
    }

    /* ── PLACEHOLDER VISUALS ── */
    .img-coffee-bar {
      background: linear-gradient(135deg, #2d4527 0%, #1a2918 100%);
      display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden;
    }
    .img-coffee-bar::before {
      content: '';
      position: absolute; inset: 0;
      background: radial-gradient(circle at 70% 30%, rgba(0,130,74,0.3), transparent 60%);
    }
    .floating-cups { display: flex; gap: 20px; align-items: flex-end; }
    .cup {
      border-radius: 8px 8px 12px 12px;
      position: relative; flex-shrink: 0;
    }
    .cup-sm { width: 50px; height: 60px; background: linear-gradient(135deg, #A0714F, #6B4226); }
    .cup-md { width: 60px; height: 75px; background: linear-gradient(135deg, #8B5E2B, #5C3D1E); }
    .cup-lg { width: 70px; height: 90px; background: linear-gradient(135deg, #00824A, #004d2e); }
    .cup::before { content: ''; position: absolute; top: -8px; left: 50%; transform: translateX(-50%); width: 70%; height: 12px; background: rgba(255,255,255,0.12); border-radius: 4px 4px 0 0; }

    .fruity-visual { position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; }
    .mango-cup {
      width: 100px; height: 130px;
      background: linear-gradient(180deg, #FFB347 0%, #FF8C00 100%);
      border-radius: 8px 8px 16px 16px;
      position: relative; box-shadow: 0 8px 24px rgba(255,140,0,0.4);
    }
    .mango-cup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 30px; background: rgba(255,255,255,0.3); border-radius: 8px 8px 0 0; }
    .matcha-cup {
      width: 85px; height: 110px;
      background: linear-gradient(180deg, #6DBF67 0%, #4a9c45 100%);
      border-radius: 8px 8px 16px 16px;
      position: relative; box-shadow: 0 8px 24px rgba(77,180,72,0.4);
      margin-left: -20px; margin-bottom: -10px; z-index: -1;
    }
    .spring-visual { display: flex; align-items: center; justify-content: center; gap: 16px; }
    .lavender-cup {
