  // Carousel state
  const carouselState = {};

  function moveCarousel(id, dir) {
    const track = document.getElementById(id + '-track');
    const outer = document.getElementById(id + '-outer');
    if (!track || !outer) return;

    const items = track.querySelectorAll('.gift-card-item');
    const itemW = items[0] ? items[0].offsetWidth + 16 : 176;
    const visibleW = outer.offsetWidth;
    const visibleCount = Math.floor(visibleW / itemW);
    const maxIndex = Math.max(0, items.length - visibleCount);

    if (!carouselState[id]) carouselState[id] = 0;
    carouselState[id] = Math.max(0, Math.min(maxIndex, carouselState[id] + dir));
    track.style.transform = `translateX(-${carouselState[id] * itemW}px)`;
  }

