    .map-pin.selected .pin-body { background: var(--green-dark); }
    .pin-body {
      width: 36px; height: 36px; border-radius: 50% 50% 50% 0%;
      transform: rotate(-45deg); background: var(--green);
      display: flex; align-items: center; justify-content: center;
      box-shadow: 0 4px 12px rgba(0,130,74,0.4);
      transition: background 0.2s;
    }
    .pin-icon { transform: rotate(45deg); width: 18px; height: 18px; fill: white; }
    .pin-label {
      position: absolute; top: -44px; left: 50%; transform: translateX(-50%);
      background: var(--forest); color: var(--white);
      padding: 4px 10px; border-radius: var(--radius-sm); font-size: 12px; font-weight: 600;
      white-space: nowrap; opacity: 0; transition: opacity 0.2s; pointer-events: none;
    }
    .map-pin:hover .pin-label { opacity: 1; }

    /* Map controls */
    .map-controls {
      position: absolute; right: 16px; top: 16px; z-index: 20;
      display: flex; flex-direction: column; gap: 4px;
    }
    .map-ctrl-btn {
      width: 36px; height: 36px; border-radius: var(--radius-sm);
      background: var(--white); border: 1px solid var(--border);
      box-shadow: var(--shadow-sm);
      display: flex; align-items: center; justify-content: center;
      font-size: 18px; font-weight: 700; color: var(--text-dark);
      transition: background var(--transition);
    }
    .map-ctrl-btn:hover { background: var(--cream-light); }

    /* Map info popup */
    .map-popup {
      position: absolute; bottom: 24px; left: 50%; transform: translateX(-50%);
      width: min(360px, calc(100% - 32px));
      background: var(--white); border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg); padding: 20px;
      display: none; z-index: 30;
    }
    .map-popup.visible { display: block; }
    .popup-close { position: absolute; top: 12px; right: 12px; padding: 4px; color: var(--text-light); }
    .popup-close:hover { color: var(--text-dark); }
    .popup-name { font-family: 'DM Sans', sans-serif; font-size: 18px; font-weight: 700; margin-bottom: 6px; }
    .popup-address { font-size: 14px; color: var(--text-mid); margin-bottom: 12px; }
    .popup-status { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; margin-bottom: 12px; }
    .popup-actions { display: flex; gap: 8px; }
    .popup-btn {
      flex: 1; padding: 10px; border-radius: 100px; text-align: center;
      font-size: 13px; font-weight: 600; transition: background var(--transition);
    }
    .popup-btn.green { background: var(--green); color: var(--white); }
    .popup-btn.green:hover { background: var(--green-dark); }
    .popup-btn.outline { border: 1.5px solid var(--border); color: var(--text-dark); }
    .popup-btn.outline:hover { background: var(--cream-light); }

    /* "Use my location" button */
    .use-location-btn {
      display: flex; align-items: center; gap: 6px;
      padding: 10px 16px; border-radius: 100px;
      border: 1.5px solid var(--border); background: var(--white);
      font-size: 14px; font-weight: 500; color: var(--text-mid);
      transition: background var(--transition), color var(--transition);
      flex-shrink: 0;
    }
    .use-location-btn:hover { background: var(--green-light); color: var(--green); border-color: var(--green); }
    .use-location-btn svg { width: 16px; height: 16px; }

    /* Footer */
    .site-footer { background: var(--forest); color: var(--white); }
    .footer-bottom { max-width: 1280px; margin: 0 auto; padding: 24px; display: flex; gap: 16px; align-items: center; justify-content: space-between; flex-wrap: wrap; }
    .footer-logo { font-family: 'DM Sans', sans-serif; font-size: 18px; font-weight: 700; color: var(--cream); }
    .footer-links { display: flex; gap: 20px; flex-wrap: wrap; }
    .footer-links a { font-size: 13px; color: rgba(255,255,255,0.7); transition: color var(--transition); }
    .footer-links a:hover { color: var(--white); }
    .footer-legal { font-size: 12px; color: rgba(255,255,255,0.5); }

    /* Responsive */
    @media (max-width: 900px) {
      .locator-layout { grid-template-columns: 1fr; height: auto; overflow: visible; }
      .results-panel { height: auto; border-right: none; border-bottom: 1px solid var(--border); }
      .map-area { height: 400px; }
    }
    @media (max-width: 600px) {
      .search-controls { padding: 12px 16px; }
      .controls-inner { gap: 8px; }
      .use-location-btn span { display: none; }
      .map-area { height: 300px; }
      .footer-bottom { flex-direction: column; text-align: center; }
    }
  </style>
