    const isPickup = type === 'pickup';
    pickupBtn.classList.toggle('active', isPickup);
    deliveryBtn.classList.toggle('active', !isPickup);
    pickupBtn.setAttribute('aria-pressed', isPickup);
    deliveryBtn.setAttribute('aria-pressed', !isPickup);
    const count = document.getElementById('resultsCount');
    count.textContent = isPickup ? 'Showing 6 stores near Seattle, WA' : 'Showing 4 delivery zones near Seattle, WA';
  }

  // Search suggestions
